190	    private fun calculateThptStats(
191	        scanResult: ScanResult, codeModel: ThptExamCodeModel, config: ThptExamConfig,
192	        canvas: Canvas?, paintCorrect: Paint, paintWrong: Paint,
193	        paintError: Paint, paintEmpty: Paint
194	    ): ThptStats {
195	        var score = 0.0; var correct = 0; var wrong = 0; var blank = 0
196	        val p1Weight = if (config.p1Questions > 0) (config.p1Score / config.p1Questions.toDouble()) else 0.0
197	        val p3Weight = if (config.p3Questions > 0) (config.p3Score / config.p3Questions.toDouble()) else 0.0
198	
199	        val validP1Questions = 1..config.p1Questions
200	        val validP2Questions = 41 until (41 + config.p2Questions * 4)
201	        val validP3Questions = 73 until (73 + config.p3Questions)
202	
203	        scanResult.answers.forEach { q ->
204	            var realAns: String? = null
205	            var statusPaint = paintEmpty
206	
207	            when (q.questionNumber) {
208	                in validP1Questions -> {
209	                    realAns = codeModel.part1[q.questionNumber.toString()]
210	                    if (q.isError) { wrong++; statusPaint = paintError }
211	                    else if (q.selectedAnswer == null) { blank++; statusPaint = paintEmpty }
212	                    else if (q.selectedAnswer == realAns) { correct++; score += p1Weight; statusPaint = paintCorrect }
213	                    else { wrong++; statusPaint = paintWrong }
214	                }
215	
216	                in validP2Questions -> {
217	                    val offset = q.questionNumber - 41
218	                    val cau = (offset / 4) + 1
219	                    val y = when (offset % 4) { 0 -> "a"; 1 -> "b"; 2 -> "c"; else -> "d" }
220	                    realAns = codeModel.part2[cau.toString()]?.get(y)
221	
222	                    if (q.isError) { wrong++; statusPaint = paintError }
223	                    else if (q.selectedAnswer == null) { blank++; statusPaint = paintEmpty }
224	                    else if (q.selectedAnswer == realAns) { correct++; statusPaint = paintCorrect }
225	                    else { wrong++; statusPaint = paintWrong }
226	                }
227	
228	                in validP3Questions -> {
229	                    val cau = q.questionNumber - 72
230	                    realAns = codeModel.part3[cau.toString()]
231	
232	                    if (q.isError) { wrong++; statusPaint = paintError }
233	                    else if (q.selectedAnswer == null) { blank++; statusPaint = paintEmpty }
234	                    else if (q.selectedAnswer == realAns) { correct++; score += p3Weight; statusPaint = paintCorrect }
235	                    else { wrong++; statusPaint = paintWrong }
236	                }
237	            }
238	
239	            q.bubbles.forEach { b ->
240	                if (b.isFilled) canvas?.drawCircle(b.x, b.y, b.radius, statusPaint)
241	                else canvas?.drawCircle(b.x, b.y, b.radius, paintEmpty)
242	            }
243	        }
244	
245	        // TÍNH ĐIỂM LŨY TIẾN CHO PHẦN II
246	        val p2Answers = scanResult.answers.filter { it.questionNumber in validP2Questions }
247	        for (i in 0 until config.p2Questions) {
248	            var correctPartsInCluster = 0
249	            for (j in 0 until 4) {
250	                val qIndex = 41 + (i * 4) + j
251	                val studentAns = p2Answers.find { it.questionNumber == qIndex }?.selectedAnswer
252	                val cau = i + 1
253	                val y = when (j) { 0 -> "a"; 1 -> "b"; 2 -> "c"; else -> "d" }
254	                val realAns = codeModel.part2[cau.toString()]?.get(y)
255	                if (studentAns != null && !p2Answers.find { it.questionNumber == qIndex }!!.isError && studentAns == realAns) {
256	                    correctPartsInCluster++
257	                }
258	            }
259	            score += when (correctPartsInCluster) { 1 -> 0.1; 2 -> 0.25; 3 -> 0.5; 4 -> 1.0; else -> 0.0 }
260	        }
261	
262	        return ThptStats(Math.min(score, 10.0), correct, wrong, blank)
263	    }
264	
265	    // Hàm này sẽ dùng để map dữ liệu từ ScanResult sang List UI cho màn hình con mắt
266	    fun getDetailedQuestionsUI(
267	        scanResult: ScanResult,
268	        codeModel: ThptExamCodeModel?,
269	        basicAnswers: Map<String, String>?,
270	        isThpt: Boolean,
271	        thptConfig: ThptExamConfig? = null,
272	        basicQuestionCount: Int = 0
273	    ): List<QuestionDetailUI> {
274	        val uiList = mutableListOf<QuestionDetailUI>()
275	
276	        val validP1 = if (thptConfig != null) 1..thptConfig.p1Questions else 1..0
277	        val validP2 = if (thptConfig != null) 41 until (41 + thptConfig.p2Questions * 4) else 1..0
278	        val validP3 = if (thptConfig != null) 73 until (73 + thptConfig.p3Questions) else 1..0
279	        val validBasic = 1..basicQuestionCount
280	
281	        scanResult.answers.forEach { q ->
282	            val num = q.questionNumber
283	
284	            // LỌC: BỎ QUA NGAY NHỮNG CÂU VƯỢT QUÁ SỐ LƯỢNG TRONG CẤU HÌNH
285	            if (isThpt && (num !in validP1 && num !in validP2 && num !in validP3)) return@forEach
286	            if (!isThpt && num !in validBasic) return@forEach
287	
288	            var studentAns = q.selectedAnswer ?: "-"
289	            if (q.isError) studentAns = "Lỗi"
290	
291	            var correctAns = ""
292	
293	            if (isThpt && codeModel != null) {
294	                when (num) {
295	                    in validP1 -> {
296	                        correctAns = codeModel.part1[num.toString()] ?: "?"
297	                        val status = if (q.isError || q.selectedAnswer == null) AnswerStatus.BLANK else if (q.selectedAnswer == correctAns) AnswerStatus.CORRECT else AnswerStatus.WRONG
298	                        uiList.add(QuestionDetailUI(num.toString(), studentAns, correctAns, status))
299	                    }
300	                    in validP2 -> {
301	                        val offset = num - 41
302	                        val cau = (offset / 4) + 1
303	                        val y = when (offset % 4) { 0 -> "a"; 1 -> "b"; 2 -> "c"; else -> "d" }
304	                        val displayLabel = "${cau}${y}"
305	                        correctAns = codeModel.part2[cau.toString()]?.get(y) ?: "?"
306	                        val status = if (q.isError || q.selectedAnswer == null) AnswerStatus.BLANK else if (q.selectedAnswer == correctAns) AnswerStatus.CORRECT else AnswerStatus.WRONG
307	                        uiList.add(QuestionDetailUI(displayLabel, studentAns, correctAns, status))
308	                    }
309	                    in validP3 -> {
310	                        val cau = num - 72
311	                        correctAns = codeModel.part3[cau.toString()] ?: "?"
312	                        val status = if (q.isError || q.selectedAnswer == null) AnswerStatus.BLANK else if (q.selectedAnswer == correctAns) AnswerStatus.CORRECT else AnswerStatus.WRONG
313	                        uiList.add(
314	                            QuestionDetailUI(
315	                                (cau + 40).toString(),
316	                                studentAns,
317	                                correctAns,
318	                                status
319	                            )
320	                        )
321	                    }
322	                }
323	            } else if (!isThpt && basicAnswers != null) {
324	                correctAns = basicAnswers[num.toString()] ?: "?"
325	                val status = if (q.isError || q.selectedAnswer == null) AnswerStatus.BLANK else if (q.selectedAnswer == correctAns) AnswerStatus.CORRECT else AnswerStatus.WRONG
326	                uiList.add(QuestionDetailUI(num.toString(), studentAns, correctAns, status))
327	            }
328	        }
329	        return uiList
330	    }
331	
332	    fun resetState() {
333	        _gradingState.value = GradingState.Idle
334	    }
335	}

