// --- CÁC COMPONENT TÁI SỬ DỤNG CHO GIAO DIỆN ---

@Composable
fun SectionTitle(title: String) {
    Text(
        text = title,
        fontSize = 15.sp,
        fontWeight = FontWeight.Bold,
        color = ColorText2,
        modifier = Modifier.padding(top = 28.dp, bottom = 12.dp, start = 8.dp)
    )
}

@Composable
fun SettingsGroup(content: @Composable ColumnScope.() -> Unit) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .shadow(
                elevation = 12.dp,
                shape = RoundedCornerShape(16.dp),
                spotColor = Color(0x26000000),
                ambientColor = Color(0x14000000)
            )
            .background(Color.White, RoundedCornerShape(16.dp))
            .clip(RoundedCornerShape(16.dp)),
        content = content
    )
}

@Composable
fun SettingItem(
    @DrawableRes icon: Int,
    title: String,
    trailingText: String? = null,
    showArrow: Boolean = true,
    onClick: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
            .padding(horizontal = 20.dp, vertical = 18.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Icon(
            painter = painterResource(id = icon),
            contentDescription = null,
            tint = PrimaryDarkBlue,
            modifier = Modifier.size(22.dp)
        )
        Spacer(modifier = Modifier.width(16.dp))

        Text(
            text = title,
            fontSize = 15.sp,
            color = ColorText,
            modifier = Modifier.weight(1f),
            fontWeight = FontWeight.Medium
        )

        if (trailingText != null) {
            Text(text = trailingText, fontSize = 15.sp, color = Color(0xFF9CA3AF))
            Spacer(modifier = Modifier.width(8.dp))
        }
        if (showArrow) {
            Icon(
                painter = painterResource(id = R.drawable.ic_arrow_right),
                contentDescription = null,
                tint = Color(0xFF999999),
                modifier = Modifier.size(16.dp)
            )
        }
    }
}

@Composable
fun LanguageOption(title: String, isSelected: Boolean, onClick: () -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
            .padding(horizontal = 24.dp, vertical = 16.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Text(
            text = title,
            fontSize = 16.sp,
            color = if (isSelected) PrimaryDarkBlue else Color.Black,
            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal
        )
        if (isSelected) {
            Icon(
                painter = painterResource(id = R.drawable.ic_check),
                contentDescription = null,
                tint = PrimaryDarkBlue,
                modifier = Modifier.size(20.dp)
            )
        }
    }
}

